  'review.sentBackToYou': { en: 'The Director sent this back. Fix what the note asks for, add photos or receipts, and send it for a final check again.', rw: 'Umuyobozi Mukuru yabigaruye. Kosora ibyo icyitonderwa gisaba, wongeremo amafoto cyangwa inyemezabwishyu, hanyuma wongere wohereze isuzuma rya nyuma.', fr: 'Le Directeur l’a renvoyé. Corrigez ce que la note demande, ajoutez photos ou reçus, puis renvoyez-le pour vérification finale.', sw: 'Mkurugenzi ameirudisha. Rekebisha kile maelezo yanachoomba, ongeza picha au risiti, kisha itume tena kwa ukaguzi wa mwisho.' },
  'review.reassignClearsAcceptance': { en: 'The new manager will be asked to accept this work.', rw: 'Umuyobozi mushya azasabwa kwemera aka kazi.', fr: 'Le nouveau responsable devra accepter ce travail.', sw: 'Meneja mpya ataombwa kukubali kazi hii.' },
