  'work.nonePlannedForYouHint': { en: 'The Director plans the month and assigns the activities. Yours will appear here.', rw: 'Umuyobozi mukuru ateganya ukwezi kandi agatanga ibikorwa. Ibyawe bizagaragara hano.', fr: 'Le Directeur planifie le mois et attribue les activités. Les vôtres apparaîtront ici.', sw: 'Mkurugenzi hupanga mwezi na kugawa shughuli. Zako zitaonekana hapa.' },
  'work.monthStillDraft': { en: 'The Director is still planning this month. You will be able to start once they have listed the activities and confirmed the budget.', rw: 'Umuyobozi mukuru aracyategura uku kwezi. Uzashobora gutangira nyuma yo gushyiraho ibikorwa no kwemeza ingengo y\'imari.', fr: 'Le Directeur planifie encore ce mois. Vous pourrez commencer une fois qu\'il aura listé les activités et confirmé le budget.', sw: 'Mkurugenzi bado anapanga mwezi huu. Utaweza kuanza baada ya kuorodhesha shughuli na kuthibitisha bajeti.' },
  'monthly.noActivitiesHint': { en: 'A month with a budget but no activities gives the manager nothing to do. Add the first one below.', rw: 'Ukwezi gufite ingengo y\'imari ariko nta bikorwa nta cyo guha umuyobozi. Ongeraho icya mbere hano hasi.', fr: 'Un mois avec un budget mais sans activités ne donne rien à faire au responsable. Ajoutez la première ci-dessous.', sw: 'Mwezi wenye bajeti lakini bila shughuli haumpi meneja chochote cha kufanya. Ongeza ya kwanza hapa chini.' },
  'monthly.nextAddActivities': { en: 'Next: list the work for this month', rw: 'Ibikurikira: shyiraho akazi k\'uku kwezi', fr: 'Ensuite : listez le travail de ce mois', sw: 'Ifuatayo: orodhesha kazi ya mwezi huu' },
