  'export.nothingAtAll': { en: 'Nothing was recorded in these dates: no days against a monthly plan, and no activities.', rw: 'Nta kintu cyanditswe muri izi tariki: nta minsi kuri gahunda y’ukwezi, nta n’ibikorwa.', fr: 'Rien n’a été enregistré sur ces dates : aucune journée sur un plan mensuel, et aucune activité.', sw: 'Hakuna kilichorekodiwa katika tarehe hizi: hakuna siku kwa mpango wa mwezi, na hakuna shughuli.' },
