  'export.monthsNotInProject': { en: '{count} month(s) in these dates are filed elsewhere, not under this project, so their commitments are not counted here.', rw: 'Amezi {count} muri izi tariki ari ahandi, si kuri uyu mushinga, bityo ibyemeranyijwe byayo ntibibarirwa hano.', fr: '{count} mois sur ces dates sont rattachés ailleurs, pas à ce projet ; leurs engagements ne sont donc pas comptés ici.', sw: 'Miezi {count} katika tarehe hizi imeorodheshwa mahali pengine, si chini ya mradi huu, hivyo makubaliano yake hayahesabiwi hapa.' },

